using UnityEngine;using LWS.TruckBowling;using LWS.TruckCornhole;using LWS.TruckCurling;using LWS.TruckKeepaway;using LWS.TruckTerrierRacing;
namespace LWS.TruckSports {
// Presentation adapter after each established mode computes its own stable camera pose.
// Interior stays at that pose; only the owning camera looks. No drive/turn input gates are touched.
[DefaultExecutionOrder(250)]public sealed class SportsLegacyCabLook:MonoBehaviour {
 public Camera view;public Transform cockpit;public SportsCabLook look;public SportsCabSteering steering;public BowlingCabCamera bowling;public CornholeCamera cornhole;public CurlingMatch curling;public KeepawayMatch keepaway;public TerrierMatch terrier;public int viewIndex;Rigidbody bound;
 static bool MouseOwner(BowlingSetup setup,int owner,bool sequential=false){if(sequential)return true;for(int i=0;i<setup.count;i++)if(setup.players[i].source==BowlingSource.Keyboard)return i==owner;return false;}
 void LateUpdate(){if(view==null||!view.enabled){look.ReleaseCursor();return;}BowlingPlayer player=null;int slot=-1;bool active=false,mouse=false;Rigidbody body=null;float max=32;
 if(bowling!=null){var lane=bowling.lane;var m=lane.match;slot=lane.ownerSlot;player=lane.Owner;mouse=MouseOwner(m.setup,slot,m.setup.mode==BowlingMode.HotSeat);active=m.InMatch&&!m.Finished&&!m.Paused&&m.menus.Screen==BowlingScreen.Play;body=lane.truck.body;max=lane.truck.handling.approachSteer;}
 else if(cornhole!=null){var course=cornhole.course;var m=course.match;slot=course.index;player=course.Owner;mouse=MouseOwner(m.setup,slot);active=m.InMatch&&!m.Paused&&!m.Finished&&!m.RoundBreak&&(course.replay==null||!course.replay.Playing)&&m.menus.Screen==CornholeScreen.Play;var truck=course.Current;if(truck!=null){body=truck.body;max=28;}}
 else if(curling!=null){slot=curling.ActiveSlot;player=curling.setup.players[slot];mouse=true;active=curling.Live&&curling.cab.activeSelf&&(curling.Phase==CurlingPhase.Approach||curling.Phase==CurlingPhase.Slide);var truck=curling.Current.truck;body=truck.body;max=truck.steerAngle;}
 else if(keepaway!=null&&viewIndex<keepaway.HumanViews){slot=keepaway.CabSlot(viewIndex);player=keepaway.setup.players[slot];mouse=MouseOwner(keepaway.setup,slot);active=keepaway.Live&&keepaway.cabVariant&&keepaway.alive[slot]&&keepaway.menus.Screen==SportsEventScreen.Play;var truck=keepaway.trucks[slot];body=truck.body;max=truck.steerAngle;}
 else if(terrier!=null&&viewIndex<terrier.HumanViews){slot=terrier.viewSlots[viewIndex];player=terrier.setup.players[slot];mouse=MouseOwner(terrier.setup,slot);active=terrier.Live&&terrier.racers[slot].Alive&&terrier.Phase!=TerrierPhase.Replay&&terrier.menus.Screen==SportsEventScreen.Play;var truck=terrier.racers[slot].truck;body=truck.body;max=truck.steerAngle;}
 if(cockpit!=null)cockpit.SetPositionAndRotation(view.transform.position,view.transform.rotation);if(bowling!=null&&bowling.lane.highlights!=null&&bowling.lane.highlights.Playing){look.ResetLook();return;}if(cornhole!=null&&cornhole.course.replay!=null&&cornhole.course.replay.Playing||curling!=null&&!curling.cab.activeSelf||keepaway!=null&&slot>=0&&!keepaway.alive[slot]||terrier!=null&&slot>=0&&!terrier.racers[slot].Alive){look.ResetLook();return;}if(steering!=null&&body!=null&&body!=bound){look.ResetLook();bound=body;steering.BindSource(ReadAngle,max,IsPaused);}view.transform.rotation=look.Apply(view.transform.rotation,player,slot,mouse,active,SportsLookOptions.Sensitivity,SportsLookOptions.InvertY);}
 float ReadAngle(){NWH.WheelController3D.WheelController[] wheels=null;if(bowling!=null)wheels=bowling.lane.truck.wheels;else if(cornhole!=null&&cornhole.course.Current!=null)wheels=cornhole.course.Current.wheels;else if(curling!=null)wheels=curling.Current.truck.wheels;else if(keepaway!=null&&viewIndex<keepaway.HumanViews)wheels=keepaway.trucks[keepaway.CabSlot(viewIndex)].wheels;else if(terrier!=null&&viewIndex<terrier.HumanViews)wheels=terrier.racers[terrier.viewSlots[viewIndex]].truck.wheels;return wheels!=null?(wheels[0].SteerAngle+wheels[1].SteerAngle)*.5f:0;}
 bool IsPaused()=>bowling!=null?bowling.lane.match.Paused:cornhole!=null?cornhole.course.match.Paused:curling!=null?curling.Paused:keepaway!=null?keepaway.Paused:terrier!=null&&terrier.Paused;
 void OnDisable(){if(look!=null)look.ReleaseCursor();}
}}
